function detectGap(text: string): KernelGapSignal {
  for (const rule of GAP_RULES) {
    if (hasAny(text, rule.whenAny)) {
      return {
        isGap: true,
        gapKey: rule.key,
        reason: rule.reason,
        severity: rule.severity,
      };
    }
  }

